#!/usr/bin/env node
/**
 * Reads public/index.html and generates src/assets.js with exported string constant.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname);
const PUBLIC = path.join(ROOT, 'public');
const OUT = path.join(ROOT, 'src', 'assets.js');

function escapeJs(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/`/g, '\\`')
    .replace(/\$/g, '\\$')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');
}

const p = path.join(PUBLIC, 'index.html');
const content = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : '';
const escaped = escapeJs(content);
const lines = [
  '// Auto-generated by bundle-assets.js - do not edit',
  '',
  `export const INDEX_HTML = \`${escaped}\`;`,
  '',
];

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, lines.join('\n'), 'utf8');
console.log('Wrote', OUT);
